import{_ as t,a,c as l,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 60 The future","link":"/life/english/new-concept/book-2/unit-03/lesson-060"},"next":{"text":"第二册：实践与进步 · Lesson 62 After the fire","link":"/life/english/new-concept/book-2/unit-03/lesson-062"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 60 The future","link":"/life/english/new-concept/book-2/unit-03/lesson-060"},"next":{"text":"第二册：实践与进步 · Lesson 62 After the fire","link":"/life/english/new-concept/book-2/unit-03/lesson-062"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-061.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-061.md"}'),i={name:"life/english/new-concept/book-2/unit-03/lesson-061.md"};function o(r,e,s,h,d,c){return a(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-61-trouble-with-the-hubble" tabindex="-1">第二册：实践与进步 · Lesson 61 Trouble with the Hubble <a class="header-anchor" href="#第二册-实践与进步-·-lesson-61-trouble-with-the-hubble" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 61 Trouble with the Hubble&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>科学设备发射后发现故障，修复计划涉及多个时间阶段；练习将来完成与被动表达。本课的语言观察是：will have been tested 表未来某点之前测试完成，区别于 will be tested 仅说将进行测试。不要把预计完成写成已经完成。完成学习后，请写一份设备检查计划，区分测试截止、结果评审与批准条件。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>telescope</td><td>/ˈtelɪskəʊp/</td><td>n.</td><td>望远镜</td><td>a space telescope</td></tr><tr><td>fault</td><td>/fɔːlt/</td><td>n.</td><td>故障；缺点</td><td>find a fault</td></tr><tr><td>launch</td><td>/lɔːntʃ/</td><td>v.</td><td>发射</td><td>launch a satellite</td></tr><tr><td>engineer</td><td>/ˌendʒɪˈnɪə/</td><td>n.</td><td>工程师</td><td>a software engineer</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put something right — 纠正、修好某事</li><li>by the end of — 到……结束之前或时</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：will have been tested 表未来某点之前测试完成，区别于 will be tested 仅说将进行测试。不要把预计完成写成已经完成。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By Friday, the replacement camera will have been tested twice.</p></blockquote><p>到周五之前，替换摄像机将完成两次测试。</p><p>will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>慢读 will have been tested 四层结构，再合并语块；重读 twice 与 both。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>By Friday, the replacement camera will have been tested twice. Engineers will compare the results on Saturday. They will approve the launch only if both tests pass.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一份设备检查计划，区分测试截止、结果评审与批准条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全被动：The camera will have ___ tested twice.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 将来完成时被动结构为 will have been done。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>批准发射需要什么条件？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Both tests must pass.</p><p><strong>解析：</strong> only if 引出必要条件，不是任选一次通过。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“到周五工程师将完成测试”写成主动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> By Friday, the engineers will have completed the tests.</p><p><strong>解析：</strong> 未来截止点前完成用 will have done。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-062">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",o]]);export{u as __pageData,b as default};
